package trigger

import (
	"{{.Module}}/sandbox/api"
)

// MatchTrigger reports whether one text meets a trigger: the comparison its
// Type names, run without regard to case when it declares IgnoreCase, and
// inverted when it declares Negate. Segmented is true for a text a prefix
// reads segment by segment — a route's path slice, a command's segments.
// Every layer matching on a declaration shares it, so a trigger reads the same
// in a route.yaml and in a command.yaml.
// Generated by `{{.GeneratorName}} build` — do not edit by hand.
func MatchTrigger(sandbox *api.Sandbox, trigger api.Trigger, text string, segmented bool) bool {
	return compareTrigger(sandbox, trigger, text, segmented) != trigger.Negate
}

// compareTrigger is the comparison of MatchTrigger before Negate. On a
// segmented text a prefix holds on a segment boundary alone — "/admin" is
// "/admin" or "/admin/…", never "/administrator"; "add" is "add" or "add …",
// never "add-flag" — which is what tells it from a text-prefix. An empty prefix
// holds on every text. A value has no segments, so there the two are one.
func compareTrigger(sandbox *api.Sandbox, trigger api.Trigger, text string, segmented bool) bool {
	value := trigger.Value
	if trigger.IgnoreCase && trigger.Type != api.RegexTrigger {
		value = sandbox.Deps.Stringsdeps.ToLower(value)
		text = sandbox.Deps.Stringsdeps.ToLower(text)
	}

	switch trigger.Type {
	case api.PrefixTrigger:
		if !segmented {
			return sandbox.Deps.Stringsdeps.HasPrefix(text, value)
		}
		separator := segmentSeparator(sandbox, text, value)
		value = sandbox.Deps.Stringsdeps.TrimSuffix(value, separator)
		return value == "" || text == value || sandbox.Deps.Stringsdeps.HasPrefix(text, value+separator)
	case api.TextPrefixTrigger:
		return sandbox.Deps.Stringsdeps.HasPrefix(text, value)
	case api.SuffixTrigger:
		return sandbox.Deps.Stringsdeps.HasSuffix(text, value)
	case api.RegexTrigger:
		if trigger.IgnoreCase {
			value = "(?i)" + value
		}
		matched, err := sandbox.Deps.Stringsdeps.MatchPattern(value, text)
		return err == nil && matched
	case api.OneOfTrigger:
		for _, one := range trigger.Values {
			if trigger.IgnoreCase {
				one = sandbox.Deps.Stringsdeps.ToLower(one)
			}
			if one == text {
				return true
			}
		}
		return false
	}
	return text == value
}

// segmentSeparator is what splits the segments of a segmented text: "/" on a
// route's path, which always starts with one, and " " on a command's segments,
// which never does.
func segmentSeparator(sandbox *api.Sandbox, text string, value string) string {
	if sandbox.Deps.Stringsdeps.HasPrefix(text, "/") || sandbox.Deps.Stringsdeps.HasPrefix(value, "/") {
		return "/"
	}
	return " "
}
